// Authoring source. Runtime imports only the generated projects.json, never solutions.
const fs = require('node:fs');
const path = require('node:path');
const projects = [], solutions = {};
const css = `*{box-sizing:border-box}body{margin:0;padding:20px;background:#090e1c;color:#edf2ff;font:16px system-ui}main{max-width:520px;margin:auto;padding:20px;border:1px solid #2a3657;border-radius:20px;background:#121a31}h1{font-size:24px}p,label{line-height:1.5}button,input,textarea,select{font:inherit;border-radius:10px;padding:12px;margin:5px 0;max-width:100%}button{background:#5f8cff;color:white;border:0;min-height:44px;cursor:pointer}input,textarea,select{background:#0b1122;color:#edf2ff;border:1px solid #344364;width:100%}pre,output{display:block;white-space:pre-wrap;overflow-wrap:anywhere;color:#51d7d0;margin-top:16px}li{margin:10px 0} .dark{background:#050810;color:#51d7d0}.active,.selected{outline:3px solid #51d7d0}.error{color:#ff8291}[hidden]{display:none!important}.bar{height:14px;background:#51d7d0;width:0}.row{display:flex;gap:8px;flex-wrap:wrap}`;
const esc = s => s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('"','&quot;');
function base(id,title,difficulty,concepts,objective,hints,explanation){return {id,title,description:objective,difficulty,concepts:concepts.split(', '),learningObjective:objective,hints:hints.split('|'),completionExplanation:explanation,css};}
function f(id,title,level,concepts,objective,hints,body,cases,options={}){
 const p=base(id,title,level,concepts,objective,hints,options.explanation||hints.split('|').at(-1));
 p.kind='function'; p.entry='solve'; p.starterJavaScript=`${options.imports||''}// ${objective}\nwindow.solve = ${options.async?'async ':''}function (input) {\n  // Write your JavaScript here. Return the result.\n};\n`;
 p.providedJavaScript=`document.querySelector('#try').addEventListener('click',async()=>{const out=document.querySelector('#output');try{const input=JSON.parse(document.querySelector('#input').value);out.textContent=JSON.stringify(await window.solve(input),null,2)??'Your function returned undefined.';}catch(error){out.textContent=error.message;}});`;
 p.html=`<main><h1>${esc(title)}</h1><label for="input">Try an input (JSON)</label><textarea id="input" rows="5">${esc(JSON.stringify(cases[0][0],null,2))}</textarea><button id="try">Try function</button><output id="output">Your result appears here.</output></main>`;
 p.cases=cases.map(([input,expected])=>({input,expected}));
 p.validationRequirements=cases.map(([input,expected])=>`${JSON.stringify(input)} → ${JSON.stringify(expected)}`);
 p.requireUnchangedInput=!!options.immutable;
 if(options.immutable)p.validationRequirements.push('Leave the original input unchanged.');
 p.instructions=`${objective}\nImplement window.solve(input) and return the result. The provided Try function button handles the form and displays your return value.\n${options.note||''}`.trim();
 projects.push(p);solutions[id]=`${options.imports||''}window.solve = ${options.async?'async ':''}function(input){${body}};`;
}
// Foundations: each exercise has its own input contract and multiple examples.
f('welcome','Welcome Badge','Beginner','variables, const, template literals','Given a name string, return "Welcome, NAME!" with whitespace trimmed.', 'Store the trimmed name in a const.|Use input.trim() to remove outside spaces.|A template literal combines fixed words and the cleaned name.', 'const name=input.trim();return `Welcome, ${name}!`;', [[' Ada ','Welcome, Ada!'],['Lin','Welcome, Lin!'],['','Welcome, !']]);
f('packing','Packing Budget','Beginner','let, numbers, arithmetic','Given {budget, price, quantity}, return the money remaining after buying supplies.', 'Calculate price times quantity first.|Start a let balance at input.budget and subtract the cost.|Return the numeric balance, including negative balances.', 'let balance=input.budget;balance-=input.price*input.quantity;return balance;', [[{budget:50,price:7,quantity:3},29],[{budget:10,price:6,quantity:2},-2],[{budget:20,price:5,quantity:0},20]]);
f('initials','Name Tag Initials','Beginner','strings, split, map','Given a name with one or more space-separated words, return uppercase initials; ignore extra spaces.', 'Trim before splitting.|Split with /\\s+/ and take the first letter of each word.|Handle a blank name before mapping letters and joining them.', 'return input.trim()?input.trim().split(/\\s+/).map(w=>w[0].toUpperCase()).join(""):"";', [['ada lovelace','AL'],['  grace   brewster hopper ','GBH'],['','']]);
f('temperature','Trail Temperature','Beginner','numbers, functions','Convert a Celsius number to Fahrenheit and return a number.', 'Multiply Celsius by 9/5.|Add 32 after multiplication.|Parentheses can make the order of operations explicit.', 'return input*9/5+32;', [[0,32],[20,68],[-40,-40]]);
f('receipt','Receipt Label','Beginner','template literals, toFixed','Given {item, price}, return "ITEM: $PRICE" with exactly two decimal places.', 'Read both properties of the object.|Use price.toFixed(2), which returns text.|Insert the fixed decimal string after a dollar sign.', 'return `${input.item}: $${input.price.toFixed(2)}`;', [[{item:'Tea',price:3},'Tea: $3.00'],[{item:'Bread',price:2.5},'Bread: $2.50']]);
f('admission','Museum Admission','Beginner','conditionals, comparison','Given an age, return 0 for ages under 5, 8 for ages 5–17, and 15 for adults.', 'Test the smallest range first.|The next branch checks age less than 18.|Return from each branch so ranges cannot overwrite each other.', 'if(input<5)return 0;if(input<18)return 8;return 15;', [[4,0],[5,8],[17,8],[18,15]]);
f('shipping','Shipping Decision','Beginner','conditionals, logical operators','Given {member, total}, return "free" if the shopper is a member or the total is at least 50; otherwise return "paid".', 'There are two independent ways to get free shipping.|Use logical OR, not AND.|A ternary expression can select the two exact labels.', 'return input.member||input.total>=50?"free":"paid";', [[{member:false,total:49},'paid'],[{member:false,total:50},'free'],[{member:true,total:0},'free']]);
f('clamp','Volume Guard','Beginner','functions, Math','Clamp a number to the inclusive range 0 through 100.', 'Values below zero become zero.|Values above 100 become 100.|Math.max and Math.min can express both bounds.', 'return Math.min(100,Math.max(0,input));', [[-5,0],[34,34],[101,100],[0,0]]);
f('duration','Podcast Duration','Beginner','numbers, remainder','Given a nonnegative integer of seconds, return "M:SS" with a two-digit seconds part.', 'Divide by 60 and floor to get minutes.|Use remainder % 60 for the leftover seconds.|Convert the remainder to a string and padStart(2,"0").', 'return `${Math.floor(input/60)}:${String(input%60).padStart(2,"0")}`;', [[0,'0:00'],[65,'1:05'],[600,'10:00']]);
f('slug','Article Slug','Beginner','strings, replace, lowercase','Convert a title to lowercase, trim it, and replace runs of whitespace with hyphens. Leave punctuation alone.', 'Start with trim() and toLowerCase().|Use a global whitespace regular expression.|replace(/\\s+/g,"-") handles multiple spaces together.', 'return input.trim().toLowerCase().replace(/\\s+/g,"-");', [['  Hello   JS ','hello-js'],['One','one'],['A & B','a-&-b']]);
f('extension','File Type Label','Beginner','strings, lastIndexOf, slice','Return the lowercase text after the last dot in a filename, or "none" when there is no dot or a trailing dot.', 'Find the last dot with lastIndexOf.|Guard both a missing dot and a final dot.|Slice from index + 1 and lowercase that suffix.', 'const i=input.lastIndexOf(".");return i<0||i===input.length-1?"none":input.slice(i+1).toLowerCase();', [['photo.PNG','png'],['archive.tar.gz','gz'],['README','none'],['file.','none']]);
f('reading','Reading Estimate','Beginner','strings, Math.ceil, conditionals','Estimate reading minutes at 200 words per minute, rounded up; whitespace-only text takes 0 minutes.', 'Trim text before deciding whether it is empty.|Count words by splitting on whitespace.|Math.ceil gives enough whole minutes for a partial minute.', 'const s=input.trim();return s?Math.ceil(s.split(/\\s+/).length/200):0;', [['hello world',1],['   ',0],[Array(201).fill('word').join(' '),2]]);
f('discount','Coupon Price','Beginner','arithmetic, rounding','Given {price, percent}, return the discounted price rounded to two decimal places as a number.', 'Find the fraction still payable: 1 - percent/100.|Multiply price by that fraction.|Number(result.toFixed(2)) keeps the result numeric.', 'return Number((input.price*(1-input.percent/100)).toFixed(2));', [[{price:80,percent:25},60],[{price:19.99,percent:10},17.99],[{price:10,percent:100},0]]);
f('leap','Leap Year Checker','Intermediate','conditionals, remainder','Return whether an integer year is a leap year: divisible by 4, except centuries unless divisible by 400.', 'A multiple of 400 is always a leap year.|A multiple of 100 otherwise is not.|Combine the divisibility rules with AND and OR.', 'return input%400===0||(input%4===0&&input%100!==0);', [[2024,true],[1900,false],[2000,true],[2023,false]]);
f('range','Step Sequence','Beginner','loops, arrays','Given {start, end, step} with positive step, return numbers from start through end inclusive at that interval; a reversed range is empty.', 'Start an empty result array.|Use a for loop beginning at start and increasing by step.|Stop once the value is larger than end.', 'const out=[];for(let n=input.start;n<=input.end;n+=input.step)out.push(n);return out;', [[{start:2,end:8,step:3},[2,5,8]],[{start:5,end:2,step:1},[]],[{start:0,end:0,step:1},[0]]]);
f('factorial','Permutation Counter','Beginner','loops, let','Return the factorial of a nonnegative integer; 0! is 1.', 'Initialize a product at 1, not zero.|Multiply by every integer from 2 through input.|The empty loop for zero correctly leaves the product at 1.', 'let product=1;for(let i=2;i<=input;i++)product*=i;return product;', [[0,1],[1,1],[5,120],[7,5040]]);
f('fizzbuzz','Signal Labels','Beginner','loops, conditionals','Given n, return labels for integers 1 through n: "FizzBuzz" for multiples of 15, "Fizz" for 3, "Buzz" for 5, otherwise the number as text.', 'Test the combined case before the single divisors.|Push one string for each integer.|Use String(i) for ordinary numbers so every output is text.', 'const out=[];for(let i=1;i<=input;i++)out.push(i%15===0?"FizzBuzz":i%3===0?"Fizz":i%5===0?"Buzz":String(i));return out;', [[0,[]],[5,['1','2','Fizz','4','Buzz']],[15,['1','2','Fizz','4','Buzz','Fizz','7','8','Fizz','Buzz','11','Fizz','13','14','FizzBuzz']]]);
f('squares','Square Tile Areas','Beginner','arrays, map','Given an array of side lengths, return a new array of square areas without changing the original.', 'Each output depends on one input length.|map creates a new array.|Return side * side from the callback.', 'return input.map(side=>side*side);', [[[2,5,0],[4,25,0]],[[],[]]],{immutable:true});
f('hot-days','Heat Advisory','Beginner','arrays, filter','Return only temperatures at least 90, preserving their original order.', 'filter keeps elements whose predicate is true.|The boundary 90 must be included.|Return the filtered array, including an empty array when nothing qualifies.', 'return input.filter(n=>n>=90);', [[[84,91,90,79],[91,90]],[[89],[]],[[],[]]]);
f('inventory','Inventory Lookup','Beginner','objects, find','Given {items: [{id, name}], id}, return the matching item name, or "Not found".', 'Search the array by id, not by position.|find returns undefined when nothing matches.|Check the found item before reading its name.', 'const item=input.items.find(x=>x.id===input.id);return item?item.name:"Not found";', [[{items:[{id:2,name:'Pen'},{id:7,name:'Book'}],id:7},'Book'],[{items:[],id:1},'Not found']]);
f('basket','Basket Total','Beginner','reduce, objects','Given an array of {price, quantity}, return the sum of line totals.', 'Multiply price and quantity for each line.|reduce accumulates a running sum.|Pass 0 as the initial value so an empty basket works.', 'return input.reduce((sum,x)=>sum+x.price*x.quantity,0);', [[[{price:3,quantity:2},{price:5,quantity:1}],11],[[],0]]);
f('average','Score Average','Beginner','reduce, arrays','Return the average of numeric scores, or null for an empty array.', 'Check length before dividing.|Sum the scores with reduce.|Divide the sum by the number of scores.', 'return input.length?input.reduce((a,b)=>a+b,0)/input.length:null;', [[[2,4,9],5],[[],null],[[10],10]]);
f('unique','Guest Deduplicator','Intermediate','Set, spread syntax','Return the first occurrence of each guest name, in arrival order.', 'A Set stores distinct values in insertion order.|Construct a Set from the input array.|Spread the Set into a new array.', 'return [...new Set(input)];', [[['Ada','Lin','Ada','Jo'],['Ada','Lin','Jo']],[[],[]]],{immutable:true});
f('sort','Race Leaderboard','Intermediate','sort, spread syntax','Given runners {name, time}, return their names ordered by ascending time. Preserve input order for ties and do not mutate input.', 'Copy the array before sort.|Compare a.time - b.time.|Map the sorted records to names.', 'return [...input].sort((a,b)=>a.time-b.time).map(x=>x.name);', [[[{name:'A',time:12},{name:'B',time:9},{name:'C',time:12}],['B','A','C']],[[],[]]],{immutable:true});
f('chunk','Photo Contact Sheets','Intermediate','loops, slice','Given {items, size} with a positive integer size, split items into arrays of at most size elements.', 'Advance an index by size each iteration.|slice(i,i+size) takes one page.|The final page may be shorter.', 'const out=[];for(let i=0;i<input.items.length;i+=input.size)out.push(input.items.slice(i,i+input.size));return out;', [[{items:[1,2,3,4,5],size:2},[[1,2],[3,4],[5]]],[{items:[],size:3},[]]]);
f('flatten','Playlist Merge','Intermediate','arrays, flat','Flatten a one-level array of playlists into one track list, preserving duplicates and order.', 'The input contains arrays, not objects.|flat(1) removes exactly one nesting level.|Do not use a Set: repeated tracks are meaningful here.', 'return input.flat(1);', [[[['a','b'],[],['a']],['a','b','a']],[[],[]]]);
f('frequency','Word Frequency','Intermediate','objects, loops, strings','Count whitespace-separated words case-insensitively; return an object of word counts. Whitespace-only input returns {}.', 'Lowercase and trim the text first.|Increment an object entry for each word.|Use Object.create(null) for safe keys such as constructor.', 'const out=Object.create(null);for(const w of input.toLowerCase().trim().split(/\\s+/).filter(Boolean))out[w]=(out[w]||0)+1;return out;', [['Tea tea coffee',{tea:2,coffee:1}],['',{}],['constructor constructor',{constructor:2}]]);
f('group','Library Shelves','Intermediate','reduce, objects','Group book titles by genre from an array of {title, genre}; return an object of title arrays.', 'Each genre becomes a key.|Initialize an empty array when you first encounter a genre.|Push titles into the corresponding array in input order.', 'return input.reduce((out,b)=>{(out[b.genre]??=[]).push(b.title);return out;},Object.create(null));', [[[{title:'Orbit',genre:'SF'},{title:'Leaf',genre:'Nature'},{title:'Mars',genre:'SF'}],{SF:['Orbit','Mars'],Nature:['Leaf']}],[[],{}]]);
f('profile','Profile Defaults','Intermediate','destructuring, default values','Given a profile object, return "NAME · CITY". Default missing name to "Guest" and missing city to "Unknown"; preserve empty strings.', 'Destructure name and city from input.|Destructuring defaults apply only to undefined.|Use a template literal with the middle-dot separator.', 'const {name="Guest",city="Unknown"}=input;return `${name} · ${city}`;', [[{name:'Ada',city:'London'},'Ada · London'],[{},'Guest · Unknown'],[{name:''},' · Unknown']]);
f('settings','Settings Patch','Intermediate','spread syntax, objects','Given {current, patch}, return a merged settings object with patch values winning; leave both inputs unchanged.', 'Spread current into a new object.|Spread patch after current.|Later properties replace earlier ones, including false and zero.', 'return {...input.current,...input.patch};', [[{current:{sound:true,size:12},patch:{sound:false}},{sound:false,size:12}],[{current:{},patch:{size:0}},{size:0}]],{immutable:true});
f('stock','Stock Update','Intermediate','map, spread syntax','Given {items: [{id, stock}], id, amount}, return a new items array with amount added only to the matching stock.', 'Map over every item.|Copy only the matching record with a new stock value.|A missing id leaves every value unchanged.', 'return input.items.map(x=>x.id===input.id?{...x,stock:x.stock+input.amount}:x);', [[{items:[{id:1,stock:4},{id:2,stock:7}],id:1,amount:-2},[{id:1,stock:2},{id:2,stock:7}]],[{items:[],id:1,amount:2},[]]],{immutable:true});
f('intersection','Shared Interests','Intermediate','Set, filter','Given {a, b} arrays of interests, return unique interests present in both, ordered by first appearance in a.', 'Use a Set of b for membership tests.|Deduplicate a before filtering.|Keep values for which the second Set has(value).', 'const b=new Set(input.b);return [...new Set(input.a)].filter(x=>b.has(x));', [[{a:['JS','Art','JS','Music'],b:['Music','JS']},['JS','Music']],[{a:['A'],b:[]},[]]]);
f('anagram','Anagram Match','Intermediate','strings, sort, functions','Given two strings in an array, return whether they are anagrams after lowercasing and removing spaces. Keep punctuation significant.', 'Create a reusable normalization function.|Remove whitespace, split characters, sort, then join.|Compare both normalized strings for exact equality.', 'const normalize=s=>s.toLowerCase().replace(/\\s/g,"").split("").sort().join("");return normalize(input[0])===normalize(input[1]);', [[['Dormitory','Dirty room'],true],[['hello','world'],false],[['a!','a'],false]]);
f('search','Catalog Search','Intermediate','filter, strings','Given {items: [{name, price}], query}, return item names containing the trimmed query case-insensitively. An empty query returns all names.', 'Normalize the query once.|Filter using name.toLowerCase().includes(query).|Map the matched records to names.', 'const q=input.query.trim().toLowerCase();return input.items.filter(x=>x.name.toLowerCase().includes(q)).map(x=>x.name);', [[{items:[{name:'Green Tea',price:4},{name:'Coffee',price:5}],query:' TEA '},['Green Tea']],[{items:[{name:'A',price:1}],query:''},['A']]]);
f('pagination','Search Page','Intermediate','slice, arithmetic','Given {items, page, pageSize}, return that 1-based page of items. An out-of-range page returns an empty array.', 'Page 1 starts at index zero.|Compute (page - 1) * pageSize.|Slice from start to start + pageSize.', 'const start=(input.page-1)*input.pageSize;return input.items.slice(start,start+input.pageSize);', [[{items:[1,2,3,4,5],page:2,pageSize:2},[3,4]],[{items:[1],page:3,pageSize:2},[]]]);
f('median','Median Sensor','Intermediate','sort, arrays','Return the median of numbers, averaging the two middle values for even length; return null for empty input and preserve input.', 'Sort a copy numerically.|Find the middle index with Math.floor(length/2).|Even arrays need the average of indices middle-1 and middle.', 'if(!input.length)return null;const a=[...input].sort((a,b)=>a-b),m=Math.floor(a.length/2);return a.length%2?a[m]:(a[m-1]+a[m])/2;', [[[8,1,3],3],[[8,2,4,10],6],[[],null]],{immutable:true});
f('transpose','Seating Rotation','Advanced','nested arrays, map','Transpose a rectangular matrix so rows become columns; return [] for an empty matrix.', 'The first row tells you how many columns exist.|Map each column index to values from every row.|Guard an empty input before reading input[0].', 'return input.length?input[0].map((_,c)=>input.map(row=>row[c])):[];', [[[[1,2,3],[4,5,6]],[[1,4],[2,5],[3,6]]],[[],[]]]);
f('run-length','Message Compressor','Advanced','loops, strings','Compress consecutive repeated characters as character plus count, including singletons. An empty string returns empty text.', 'Track the character at the current index.|Move a second index while the character remains the same.|Append the character and run length, then skip to the next run.', 'let out="";for(let i=0;i<input.length;){let j=i+1;while(input[j]===input[i]&&j<input.length)j++;out+=input[i]+(j-i);i=j;}return out;', [['aaabbc','a3b2c1'],['ababa','a1b1a1b1a1'],['','']]);
f('brackets','Bracket Balance','Advanced','arrays, stack, loops','Return whether (), [] and {} are correctly balanced and nested. Ignore all other characters.', 'Push opening brackets onto a stack.|Each closing bracket must match the last opening bracket.|At the end the stack must be empty.', 'const stack=[],pairs={")":"(","]":"[","}":"{"};for(const c of input){if("([{ ".trim().includes(c))stack.push(c);else if(pairs[c]&&stack.pop()!==pairs[c])return false;}return stack.length===0;', [['a(b[c]{d})',true],['([)]',false],['(',false],['',true]]);
f('query','Query String Builder','Intermediate','Object.entries, map, encodeURIComponent','Given a flat object of string values, return URL query pairs in object entry order, encoding both keys and values.', 'Use Object.entries to get key/value pairs.|Encode both sides with encodeURIComponent.|Join each pair with = and the full list with &.', 'return Object.entries(input).map(([k,v])=>`${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join("&");', [[{q:'green tea',page:'2'},'q=green%20tea&page=2'],[{},''],[{'a&b':'x=y'},'a%26b=x%3Dy']]);
f('date-key','UTC Date Label','Intermediate','Date, strings','Given a valid ISO timestamp, return its UTC calendar date as YYYY-MM-DD.', 'Construct a Date from the timestamp.|toISOString always expresses the date in UTC.|Take the first ten characters.', 'return new Date(input).toISOString().slice(0,10);', [['2026-03-01T01:00:00+02:00','2026-02-28'],['2024-02-29T12:00:00Z','2024-02-29']]);
f('days-between','Trip Length','Intermediate','Date, arithmetic','Given [start, end] date-only YYYY-MM-DD strings, return the signed number of days from start to end using UTC.', 'Date-only ISO strings parse in UTC.|Subtract timestamps to get milliseconds.|Divide by 86,400,000 milliseconds per day.', 'return (Date.parse(input[1])-Date.parse(input[0]))/86400000;', [[['2024-02-28','2024-03-01'],2],[['2026-01-02','2026-01-01'],-1],[['2026-01-01','2026-01-01'],0]]);
f('weekday','Weekend Planner','Intermediate','Date, conditionals','Given a date-only YYYY-MM-DD string, return whether it is Saturday or Sunday in UTC.', 'Build a Date from the string.|getUTCDay returns 0 for Sunday and 6 for Saturday.|Check both values with logical OR.', 'const day=new Date(input).getUTCDay();return day===0||day===6;', [['2026-09-05',true],['2026-09-06',true],['2026-09-07',false]]);
f('safe-json','Safe JSON Reader','Intermediate','JSON.parse, error handling','Given JSON text, return {ok: true, value: parsedValue}, or {ok: false, value: null} if parsing fails.', 'JSON.parse can throw a SyntaxError.|Wrap parsing in try/catch.|Return a consistent object shape from both branches.', 'try{return {ok:true,value:JSON.parse(input)}}catch{return {ok:false,value:null}}', [['{"a":1}',{ok:true,value:{a:1}}],['oops',{ok:false,value:null}],['null',{ok:true,value:null}]]);
f('validate-record','Signup Record','Intermediate','objects, error handling, arrays','Given {name, age}, return an array of errors in this order: "Name required" if name is blank, then "Adult required" if age is not an integer at least 18.', 'Build an errors array instead of returning after the first problem.|Trim name before checking emptiness.|Number.isInteger rejects fractional ages as well as non-numbers.', 'const errors=[];if(!input.name.trim())errors.push("Name required");if(!Number.isInteger(input.age)||input.age<18)errors.push("Adult required");return errors;', [[{name:' ',age:16},['Name required','Adult required']],[{name:'Ada',age:18},[]],[{name:'Jo',age:18.5},['Adult required']]]);
f('nested-total','Folder Size','Advanced','recursion, reduce','Given a nested array of numbers and arrays, return the sum of all numbers at any depth.', 'Write a helper that handles one value.|If it is an array, reduce its recursively calculated totals.|A number is the base case and returns itself.', 'function total(x){return Array.isArray(x)?x.reduce((s,v)=>s+total(v),0):x}return total(input);', [[[1,[2,[3]],4],10],[[],0],[[[-2],5],3]]);
f('binary-search','Shelf Search','Advanced','loops, binary search','Given {items, target} with sorted distinct numbers, return the target index or -1 using binary search.', 'Keep low and high inclusive bounds.|Compare the middle value with target.|Discard half the range each iteration and return -1 if the bounds cross.', 'let low=0,high=input.items.length-1;while(low<=high){const mid=Math.floor((low+high)/2);if(input.items[mid]===input.target)return mid;if(input.items[mid]<input.target)low=mid+1;else high=mid-1;}return -1;', [[{items:[2,4,8,16,32],target:16},3],[{items:[2,4],target:3},-1],[{items:[],target:1},-1]]);
f('intervals','Meeting Merge','Advanced','sort, loops, spread syntax','Merge overlapping or touching [start,end] meeting intervals, returning sorted intervals without mutating input.', 'Copy each interval before sorting by start.|Compare the next start with the last merged end.|Extend an overlap using Math.max; otherwise append a new interval.', 'const a=input.map(x=>[...x]).sort((a,b)=>a[0]-b[0]),out=[];for(const x of a){const last=out.at(-1);if(last&&x[0]<=last[1])last[1]=Math.max(last[1],x[1]);else out.push(x);}return out;', [[[[5,7],[1,3],[3,6],[9,10]],[[1,7],[9,10]]],[[],[]]],{immutable:true});
f('diff','Settings Difference','Advanced','Object.keys, Set, objects','Given {before, after} flat settings objects, return alphabetically sorted keys whose primitive values changed, appeared, or disappeared.', 'Collect the union of both key sets.|A missing key differs from a present key, even if its value is null.|Filter changed keys, then sort the names.', 'return [...new Set([...Object.keys(input.before),...Object.keys(input.after)])].filter(k=>!(k in input.before)||!(k in input.after)||input.before[k]!==input.after[k]).sort();', [[{before:{a:1,b:2},after:{a:1,b:3,c:false}},['b','c']],[{before:{x:null},after:{}},['x']],[{before:{},after:{}},[]]]);
f('money-split','Fair Bill Split','Advanced','numbers, arrays, remainder','Given {cents, people} with nonnegative integer cents and positive people, split cents as evenly as possible. Give one extra cent to the earliest people until the remainder is used.', 'Compute the base share with Math.floor.|Find the remainder using %.|Array.from can assign base + 1 to indices below the remainder.', 'const base=Math.floor(input.cents/input.people),extra=input.cents%input.people;return Array.from({length:input.people},(_,i)=>base+(i<extra?1:0));', [[{cents:1000,people:3},[334,333,333]],[{cents:2,people:4},[1,1,0,0]],[{cents:0,people:2},[0,0]]]);
const click=selector=>({action:'click',selector});
const enter=(selector,value,event='input')=>({action:'input',selector,value,event});
const check=(selector,value,property='textContent')=>({action:'expect',selector,property,value});
const wait=ms=>({action:'wait',ms});
const event=(selector,event)=>({action:'event',selector,event});
function d(id,title,level,concepts,mission,html,starter,hints,body,steps,requirements,options={}){
 const p=base(id,title,level,concepts,mission,hints,options.explanation||hints.split('|').at(-1));
 Object.assign(p,{kind:'dom',instructions:mission,html:`<main>${html}</main>`,starterJavaScript:starter+'\n\n// Implement the mission here.\n',providedJavaScript:'',steps,validationRequirements:requirements,storageSeed:options.storageSeed||{}});
 projects.push(p);solutions[id]=body;
}
d('counter','Pocket Counter','Beginner','let, DOM selection, event listeners','Wire +, − and Reset. Start at zero, increase/decrease by one, and never go below zero.', '<h1 id="count">0</h1><button id="minus">−</button><button id="reset">Reset</button><button id="plus">+</button>', 'let count = 0;\nconst display = document.querySelector("#count");','Keep the number in a let variable.|Update textContent after every action.|Clamp decrement with Math.max(0,count-1) and reset to zero.', 'let n=0;const out=document.querySelector("#count");document.querySelector("#plus").onclick=()=>out.textContent=++n;document.querySelector("#minus").onclick=()=>out.textContent=n=Math.max(0,n-1);document.querySelector("#reset").onclick=()=>out.textContent=n=0;', [click('#minus'),check('#count','0'),click('#plus'),click('#plus'),check('#count','2'),click('#minus'),check('#count','1'),click('#reset'),check('#count','0')],['Decrement at zero stays zero.','Two increments show 2; decrement shows 1.','Reset returns to zero.']);
d('mood','Mood Palette','Beginner','dataset, forEach, style','For each color button, set #swatch backgroundColor to its data-color and #choice text to its label.', '<h1>Pick a mood</h1><div id="swatch">Color sample</div><p id="choice">Choose a color</p><button data-color="coral">Coral</button><button data-color="teal">Teal</button>', 'const buttons = document.querySelectorAll("[data-color]");','Loop over the selected buttons.|Read button.dataset.color in the listener.|Assign the color to style.backgroundColor and the label to textContent.', 'document.querySelectorAll("[data-color]").forEach(b=>b.onclick=()=>{document.querySelector("#swatch").style.backgroundColor=b.dataset.color;document.querySelector("#choice").textContent=b.textContent;});',[click('[data-color="coral"]'),check('#swatch','coral','style.backgroundColor'),check('#choice','Coral'),click('[data-color="teal"]'),check('#swatch','teal','style.backgroundColor'),check('#choice','Teal')],['Coral and Teal each update both the sample and label.']);
d('tip-ui','Table Tip','Beginner','Number, forms, arithmetic','On form submit, prevent navigation and display the bill plus tip as a two-decimal number in #total. Inputs are nonnegative.', '<h1>Table tip</h1><form id="form"><label>Bill<input id="bill" type="number" value="40"></label><label>Tip %<input id="percent" type="number" value="20"></label><button>Calculate</button></form><output id="total">—</output>', 'const form = document.querySelector("#form");','Listen to submit, including keyboard submissions.|Convert input values using Number.|Compute bill*(1+percent/100) and format with toFixed(2).','document.querySelector("#form").onsubmit=e=>{e.preventDefault();document.querySelector("#total").textContent=(Number(document.querySelector("#bill").value)*(1+Number(document.querySelector("#percent").value)/100)).toFixed(2);}',[event('#form','submit'),check('#total','48.00'),enter('#bill','15'),enter('#percent','10'),event('#form','submit'),check('#total','16.50')],['Submitting 40 at 20% gives 48.00.','Submitting 15 at 10% gives 16.50.','Submission must be prevented.']);
d('tasks','Quick Task List','Beginner','DOM manipulation, createElement, remove','Add trimmed nonempty tasks as li elements to #list when Add is tapped. Clear the input after adding. Tapping a task removes it.', '<h1>Small tasks</h1><input id="task" aria-label="Task"><button id="add">Add</button><ul id="list"></ul>', 'const input = document.querySelector("#task");\nconst list = document.querySelector("#list");','Ignore input.value.trim() when empty.|Create an li and assign textContent, never insert user text as HTML.|Give the new li a click listener that calls remove().','const i=document.querySelector("#task"),list=document.querySelector("#list");document.querySelector("#add").onclick=()=>{if(!i.value.trim())return;const li=document.createElement("li");li.textContent=i.value.trim();li.onclick=()=>li.remove();list.append(li);i.value="";};',[enter('#task','   '),click('#add'),check('#list',0,'children.length'),enter('#task',' Read '),click('#add'),check('#list li','Read'),check('#task','','value'),enter('#task','Build'),click('#add'),check('#list',2,'children.length'),click('#list li'),check('#list',1,'children.length'),check('#list li','Build')],['Blank tasks are ignored.','Trimmed tasks are added and the input clears.','Tapping a task removes only that task.']);
d('characters','Message Meter','Beginner','input events, strings, DOM selection','Update #count on every input event with the current JavaScript string length, including spaces.', '<h1>Message meter</h1><textarea id="message"></textarea><output id="count">—</output>', 'const message = document.querySelector("#message");','Use input rather than change.|Read message.value.length.|Replace the output each time, including when the input becomes empty.','document.querySelector("#message").oninput=e=>document.querySelector("#count").textContent=e.target.value.length;',[enter('#message','Hi JS'),check('#count','5'),enter('#message',''),check('#count','0')],['"Hi JS" counts as 5.','Clearing the field shows 0.']);
d('greeting-ui','Personal Greeting','Beginner','strings, conditionals, click events','On Greet, display "Hello, NAME!" using the trimmed name, or "Enter a name" for blank input.', '<h1>Say hello</h1><input id="name"><button id="greet">Greet</button><output id="greeting">—</output>', 'const name = document.querySelector("#name");','Read the value inside the click callback.|Trim before checking whether it is empty.|Choose the greeting or the exact empty-input message.','document.querySelector("#greet").onclick=()=>{const n=document.querySelector("#name").value.trim();document.querySelector("#greeting").textContent=n?`Hello, ${n}!`:"Enter a name";};',[enter('#name',' Ada '),click('#greet'),check('#greeting','Hello, Ada!'),enter('#name',' '),click('#greet'),check('#greeting','Enter a name')],['Names are trimmed and included in the greeting.','Blank input gets the requested feedback.']);
d('theme','Theme Switcher','Beginner','classList, booleans','Each click toggles the dark class on #card and sets the button aria-pressed attribute to "true" or "false" to match.', '<section id="card"><h1>Theme card</h1><button id="toggle" aria-pressed="false">Toggle theme</button></section>', 'const card = document.querySelector("#card");','classList.toggle returns whether the class is now present.|Use that boolean to update aria-pressed.|setAttribute converts the boolean to text.','document.querySelector("#toggle").onclick=e=>e.target.setAttribute("aria-pressed",String(document.querySelector("#card").classList.toggle("dark")));',[click('#toggle'),check('#card',true,'class:dark'),check('#toggle','true','attr:aria-pressed'),click('#toggle'),check('#card',false,'class:dark'),check('#toggle','false','attr:aria-pressed')],['Both appearance and accessibility state toggle on and off.']);
d('accordion','Answer Revealer','Beginner','hidden, event listeners','Toggle #answer.hidden and keep #question aria-expanded in sync when the question is clicked.', '<h1>One question</h1><button id="question" aria-expanded="false">What is the DOM?</button><p id="answer" hidden>Document Object Model</p>', 'const answer = document.querySelector("#answer");','hidden is a boolean property.|Reverse it with !.|aria-expanded is the opposite of hidden.','document.querySelector("#question").onclick=e=>{const a=document.querySelector("#answer");a.hidden=!a.hidden;e.target.setAttribute("aria-expanded",String(!a.hidden));};',[click('#question'),check('#answer',false,'hidden'),check('#question','true','attr:aria-expanded'),click('#question'),check('#answer',true,'hidden'),check('#question','false','attr:aria-expanded')],['The answer opens and closes.','aria-expanded matches visibility.']);
d('password-ui','Password Checklist','Beginner','conditionals, regular expressions','On input, show "Ready" only when the password has at least 8 characters and at least one digit; otherwise show "Keep going".', '<h1>Practice password</h1><input id="password" type="text"><output id="strength">—</output>', 'const password = document.querySelector("#password");','Use the input event.|Check length and /\\d/.test(value).|Both conditions must pass with &&.','document.querySelector("#password").oninput=e=>document.querySelector("#strength").textContent=e.target.value.length>=8&&/\\d/.test(e.target.value)?"Ready":"Keep going";',[enter('#password','abcdefgh'),check('#strength','Keep going'),enter('#password','abc123'),check('#strength','Keep going'),enter('#password','abcdefg1'),check('#strength','Ready')],['A long password without digits is rejected.','A short password is rejected.','Eight characters including a digit passes.']);
d('word-ui','Word Counter','Beginner','trim, split, input events','Count whitespace-separated words live in #words; empty or whitespace-only text counts as 0.', '<h1>Word count</h1><textarea id="text"></textarea><output id="words">—</output>', 'const text = document.querySelector("#text");','Trim the text first.|Split nonempty text with /\\s+/.|Do not count the single empty string produced by splitting blank text.','document.querySelector("#text").oninput=e=>{const t=e.target.value.trim();document.querySelector("#words").textContent=t?t.split(/\\s+/).length:0;};',[enter('#text',' one   two\nthree '),check('#words','3'),enter('#text','  '),check('#words','0')],['Mixed whitespace separates three words.','Whitespace-only text counts as zero.']);
d('tabs','Profile Tabs','Intermediate','dataset, classList, forEach','When a tab is clicked, show its data-content in #panel and apply active only to that button.', '<h1>Profile</h1><div id="tabs"><button data-content="About Ada">About</button><button data-content="Projects by Ada">Projects</button><button data-content="Contact Ada">Contact</button></div><p id="panel">Select a tab</p>', 'const tabs = document.querySelectorAll("[data-content]");','Loop over tabs to connect clicks.|Remove active from all tabs before adding it to the clicked one.|Use dataset.content as the panel text.','const tabs=document.querySelectorAll("[data-content]");tabs.forEach(t=>t.onclick=()=>{tabs.forEach(x=>x.classList.remove("active"));t.classList.add("active");document.querySelector("#panel").textContent=t.dataset.content;});',[click('[data-content="Projects by Ada"]'),check('#panel','Projects by Ada'),check('[data-content="Projects by Ada"]',true,'class:active'),click('[data-content="Contact Ada"]'),check('#panel','Contact Ada'),check('[data-content="Projects by Ada"]',false,'class:active'),check('[data-content="Contact Ada"]',true,'class:active')],['Selected content is displayed.','Only the most recently selected tab is active.']);
d('progress-ui','Upload Progress','Beginner','Math.min, style, numbers','Each Advance tap adds 25 to progress, capped at 100. Update #value text and #bar width as a percent.', '<h1>Upload simulator</h1><div id="bar" class="bar"></div><output id="value">0</output><button id="advance">Advance</button>', 'let progress = 0;','Use Math.min to cap the next value.|textContent shows the number without a percent sign.|style.width needs the percent suffix.','let p=0;document.querySelector("#advance").onclick=()=>{p=Math.min(100,p+25);document.querySelector("#value").textContent=p;document.querySelector("#bar").style.width=p+"%";};',[click('#advance'),check('#value','25'),check('#bar','25%','style.width'),click('#advance'),click('#advance'),click('#advance'),click('#advance'),check('#value','100'),check('#bar','100%','style.width')],['First advance displays 25 and 25% width.','Repeated advance stops at 100.']);
d('quiz-ui','JavaScript Quiz','Beginner','dataset, conditionals','For answer clicks, show "Correct" when data-correct is "true", otherwise "Try again".', '<h1>Which declares a constant?</h1><button data-correct="false">var</button><button data-correct="true">const</button><output id="feedback">—</output>', 'const answers = document.querySelectorAll("[data-correct]");','Dataset values are strings.|Compare with the string "true".|Update the feedback for both correct and incorrect choices.','document.querySelectorAll("[data-correct]").forEach(b=>b.onclick=()=>document.querySelector("#feedback").textContent=b.dataset.correct==="true"?"Correct":"Try again");',[click('[data-correct="false"]'),check('#feedback','Try again'),click('[data-correct="true"]'),check('#feedback','Correct')],['Incorrect and correct answers receive distinct feedback.']);
d('expense-ui','Expense Envelope','Beginner','let, Number, toFixed','Add positive amounts to a running total on Add. Ignore zero and negative amounts. Show total with two decimals.', '<h1>Expense envelope</h1><input id="amount" type="number"><button id="add">Add</button><output id="total">0.00</output>', 'let total = 0;','Convert the input to Number.|Only accumulate amounts greater than zero.|Render total.toFixed(2) after each click.','let total=0;document.querySelector("#add").onclick=()=>{const n=Number(document.querySelector("#amount").value);if(n>0)total+=n;document.querySelector("#total").textContent=total.toFixed(2);};',[enter('#amount','12.5'),click('#add'),enter('#amount','2'),click('#add'),check('#total','14.50'),enter('#amount','-3'),click('#add'),check('#total','14.50')],['Multiple expenses accumulate.','Negative expenses are ignored.']);
d('email-form','Email Form','Intermediate','forms, preventDefault, error handling','On form submission, prevent navigation. Show "Accepted" for a value with non-space text before @, after @ and after a dot; otherwise show "Invalid email". This is a practice rule, not full email verification.', '<h1>Mailing list</h1><form id="signup" novalidate><input id="email"><button>Join</button></form><output id="message">—</output>', 'const form = document.querySelector("#signup");','Listen for submit on the form.|Call preventDefault before checking the value.|A pattern such as /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/ covers this exercise.','document.querySelector("#signup").onsubmit=e=>{e.preventDefault();document.querySelector("#message").textContent=/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(document.querySelector("#email").value)?"Accepted":"Invalid email";};',[enter('#email','ada@example.com'),event('#signup','submit'),check('#message','Accepted'),enter('#email','ada@'),event('#signup','submit'),check('#message','Invalid email'),enter('#email','a b@example.com'),event('#signup','submit'),check('#message','Invalid email')],['Valid practice address accepted.','Missing domain or internal spaces rejected.','Form submission is prevented.']);
d('favorites-ui','Favorite Foods','Intermediate','Set, createElement, dataset','Add a clicked food to #favorites as an li. Do not add the same food twice.', '<h1>Favorite foods</h1><button data-food="Tacos">Tacos</button><button data-food="Pasta">Pasta</button><ul id="favorites"></ul>', 'const favorites = new Set();','Track chosen names in a Set.|Return early if the name is already present.|Create and append one li only for new names.','const s=new Set();document.querySelectorAll("[data-food]").forEach(b=>b.onclick=()=>{if(s.has(b.dataset.food))return;s.add(b.dataset.food);const li=document.createElement("li");li.textContent=b.dataset.food;document.querySelector("#favorites").append(li);});',[click('[data-food="Tacos"]'),click('[data-food="Tacos"]'),check('#favorites',1,'children.length'),click('[data-food="Pasta"]'),check('#favorites',2,'children.length'),check('#favorites li:last-child','Pasta')],['Repeated selections do not duplicate foods.','A different food is appended.']);
d('calculator-ui','Four Operations','Intermediate','functions, dataset, conditionals','Calculate a and b using the clicked data-op (+, -, *, /). Show the numeric result, or "Cannot divide by zero" for division by zero.', '<h1>Calculator</h1><input id="a" type="number" value="8"><input id="b" type="number" value="2"><button data-op="+">+</button><button data-op="-">−</button><button data-op="*">×</button><button data-op="/">÷</button><output id="result">—</output>', 'const buttons = document.querySelectorAll("[data-op]");','Read fresh numeric input on every click.|Use if/else or switch instead of eval.|Handle a zero divisor before division.','document.querySelectorAll("[data-op]").forEach(b=>b.onclick=()=>{const a=Number(document.querySelector("#a").value),n=Number(document.querySelector("#b").value),op=b.dataset.op;document.querySelector("#result").textContent=op==="+"?a+n:op==="-"?a-n:op==="*"?a*n:n===0?"Cannot divide by zero":a/n;});',[click('[data-op="+"]'),check('#result','10'),click('[data-op="-"]'),check('#result','6'),click('[data-op="*"]'),check('#result','16'),click('[data-op="/"]'),check('#result','4'),enter('#b','0'),click('[data-op="/"]'),check('#result','Cannot divide by zero')],['All four operations produce correct results.','Division by zero gets explicit feedback.']);
d('live-filter','Live Library Filter','Intermediate','DOM selection, loops, hidden','As #search changes, hide list items whose text does not include the trimmed query case-insensitively. Empty search reveals all.', '<h1>Library</h1><input id="search"><ul><li id="book-a">JavaScript Patterns</li><li id="book-b">CSS Layout</li><li id="book-c">JavaScript Basics</li></ul>', 'const books = document.querySelectorAll("li");','Normalize both query and item text.|Assign each item.hidden to the inverse of includes().|An empty string is included in every string.','document.querySelector("#search").oninput=e=>document.querySelectorAll("li").forEach(li=>li.hidden=!li.textContent.toLowerCase().includes(e.target.value.trim().toLowerCase()));',[enter('#search',' JAVASCRIPT '),check('#book-a',false,'hidden'),check('#book-b',true,'hidden'),check('#book-c',false,'hidden'),enter('#search',''),check('#book-b',false,'hidden')],['Search hides only nonmatching books.','Clearing the search reveals every book.']);
d('delegation','Delegated Task Removal','Intermediate','event delegation, closest, remove','Use a click listener on #list to remove the li containing a clicked .remove button, including clicks on its nested span. Clicking task text must do nothing.', '<h1>Clean the list</h1><ul id="list"><li>Read <button class="remove"><span id="remove-inner">Remove</span></button></li><li id="keep">Build <button class="remove">Remove</button></li></ul>', 'const list = document.querySelector("#list");','Event targets may be nested inside the button.|Find event.target.closest(".remove").|Only remove its closest li when such a button exists.','document.querySelector("#list").onclick=e=>{const b=e.target.closest(".remove");if(b)b.closest("li").remove();};',[click('#keep'),check('#list',2,'children.length'),click('#remove-inner'),check('#list',1,'children.length'),check('#keep',true,'exists')],['Task text clicks do not remove items.','Nested button content triggers removal of the correct task.']);
d('select-all','Checklist Controls','Intermediate','checkboxes, change events, every','The master checkbox sets both item checkboxes to its checked state. Changing an item updates master.checked to whether all items are checked.', '<h1>Packing checklist</h1><label><input id="all" type="checkbox">All</label><label><input id="one" class="item" type="checkbox">Water</label><label><input id="two" class="item" type="checkbox">Map</label>', 'const master = document.querySelector("#all");\nconst items = [...document.querySelectorAll(".item")];','Use change events for checkboxes.|For master changes, assign its checked value to each item.|For item changes, use items.every(item=>item.checked).','const m=document.querySelector("#all"),items=[...document.querySelectorAll(".item")];m.onchange=()=>items.forEach(i=>i.checked=m.checked);items.forEach(i=>i.onchange=()=>m.checked=items.every(x=>x.checked));',[click('#all'),check('#one',true,'checked'),check('#two',true,'checked'),click('#one'),check('#all',false,'checked'),click('#one'),check('#all',true,'checked'),click('#all'),check('#two',false,'checked')],['Master selects and deselects all items.','Individual changes update the master state.']);
d('stepper','Booking Stepper','Intermediate','arrays, hidden, disabled','Show one of three sections at a time. Next and Back move between them. Disable Back initially, Next on the last section, and never go out of bounds.', '<h1>Booking</h1><section id="s0">Choose dates</section><section id="s1" hidden>Add guests</section><section id="s2" hidden>Review</section><button id="back" disabled>Back</button><button id="next">Next</button>', 'let index = 0;\nconst steps = [...document.querySelectorAll("section")];','Create a render function for visibility and button state.|Keep the index between 0 and steps.length-1.|Call render after each navigation action.','let i=0;const s=[...document.querySelectorAll("section")],back=document.querySelector("#back"),next=document.querySelector("#next");function render(){s.forEach((x,n)=>x.hidden=n!==i);back.disabled=i===0;next.disabled=i===s.length-1;}back.onclick=()=>{i=Math.max(0,i-1);render();};next.onclick=()=>{i=Math.min(s.length-1,i+1);render();};render();',[click('#next'),check('#s0',true,'hidden'),check('#s1',false,'hidden'),click('#next'),check('#s2',false,'hidden'),check('#next',true,'disabled'),click('#back'),check('#s1',false,'hidden'),click('#back'),check('#back',true,'disabled')],['Exactly the selected step is visible.','Boundary navigation buttons become disabled.']);
d('sort-table','Score Table','Intermediate','sort, DOM manipulation, dataset','Sort the existing rows ascending by numeric data-score when Sort is clicked. Keep the actual rows and their names together.', '<h1>Scores</h1><button id="sort">Sort</button><table><tbody id="rows"><tr data-score="100"><td>Ada</td><td>100</td></tr><tr data-score="9"><td>Lin</td><td>9</td></tr><tr data-score="42"><td>Jo</td><td>42</td></tr></tbody></table>', 'const rows = document.querySelector("#rows");','Select rows into an array.|Compare Number(a.dataset.score) with Number(b.dataset.score).|Appending an existing row moves it; it does not duplicate it.','document.querySelector("#sort").onclick=()=>{const p=document.querySelector("#rows");[...p.children].sort((a,b)=>Number(a.dataset.score)-Number(b.dataset.score)).forEach(x=>p.append(x));};',[click('#sort'),check('#rows tr:first-child','9','attr:data-score'),check('#rows tr:last-child','100','attr:data-score'),check('#rows tr:first-child td','Lin'),click('#sort'),check('#rows',3,'children.length')],['Scores sort numerically as 9, 42, 100.','Names stay with their rows and no rows are duplicated.']);
d('cart-ui','Quantity Cart','Intermediate','input events, reduce, dataset','Recalculate #total when either quantity input changes. Each line costs data-price times quantity. Show two decimal places.', '<h1>Small cart</h1><label>Tea $4<input id="tea" data-price="4" type="number" min="0" value="1"></label><label>Bread $3<input id="bread" data-price="3" type="number" min="0" value="1"></label><output id="total">7.00</output>', 'const quantities = [...document.querySelectorAll("[data-price]")];','Read all quantities after each change.|Use reduce with an initial sum of zero.|Multiply Number(value) by Number(dataset.price) for each item.','const q=[...document.querySelectorAll("[data-price]")];q.forEach(x=>x.oninput=()=>document.querySelector("#total").textContent=q.reduce((s,x)=>s+Number(x.value)*Number(x.dataset.price),0).toFixed(2));',[enter('#tea','3'),check('#total','15.00'),enter('#bread','0'),check('#total','12.00'),enter('#tea','0'),check('#total','0.00')],['Both quantity fields affect the total.','Zero quantities contribute zero.']);
d('rating','Star Rating','Intermediate','dataset, classList, loops','Clicking a numbered star sets #rating and applies selected to every star up to that number, removing it from later stars.', '<h1>Rate this lesson</h1>'+[1,2,3,4,5].map(n=>`<button data-star="${n}">${n} ★</button>`).join('')+'<output id="rating">0</output>', 'const stars = document.querySelectorAll("[data-star]");','Convert the clicked dataset.star to a number.|Use classList.toggle("selected",condition) on every star.|Recompute all classes when selecting a lower rating.','const stars=document.querySelectorAll("[data-star]");stars.forEach(b=>b.onclick=()=>{const n=Number(b.dataset.star);document.querySelector("#rating").textContent=n;stars.forEach(s=>s.classList.toggle("selected",Number(s.dataset.star)<=n));});',[click('[data-star="4"]'),check('#rating','4'),check('[data-star="3"]',true,'class:selected'),check('[data-star="5"]',false,'class:selected'),click('[data-star="2"]'),check('#rating','2'),check('[data-star="3"]',false,'class:selected')],['Stars up to the rating are highlighted.','Lowering the rating removes extra highlights.']);
d('safe-comment','Safe Comment Card','Intermediate','textContent, createElement, forms','On submit, prevent navigation and append a p containing trimmed nonempty comment text. Treat markup characters as literal text.', '<h1>Leave a comment</h1><form id="form"><textarea id="comment"></textarea><button>Post</button></form><section id="comments"></section>', 'const comments = document.querySelector("#comments");','Create a p element for each accepted comment.|Use textContent instead of innerHTML for user text.|Skip blank comments and prevent form submission.','document.querySelector("#form").onsubmit=e=>{e.preventDefault();const t=document.querySelector("#comment").value.trim();if(!t)return;const p=document.createElement("p");p.textContent=t;document.querySelector("#comments").append(p);};',[enter('#comment','<b>Hello</b>'),event('#form','submit'),check('#comments p','<b>Hello</b>'),check('#comments b',false,'exists'),enter('#comment',' '),event('#form','submit'),check('#comments',1,'children.length')],['HTML-like input remains literal text.','Blank comments are ignored and submit is prevented.']);
d('storage-note','Persistent Note','Intermediate','localStorage, input events','Restore localStorage key "note" into the textarea on load, defaulting to empty text. Save its value on every input event.', '<h1>Local notebook</h1><textarea id="note"></textarea>', 'const note = document.querySelector("#note");','getItem returns null when a key is missing.|Use ?? "" to supply the default.|Call setItem("note",note.value) when input changes.','const n=document.querySelector("#note");n.value=localStorage.getItem("note")??"";n.oninput=()=>localStorage.setItem("note",n.value);',[check('#note','Saved thought','value'),enter('#note','New thought'),{action:'storage',key:'note',value:'New thought'},enter('#note',''),{action:'storage',key:'note',value:''}],['Existing note is restored on load.','Edits and empty text are persisted.'],{storageSeed:{note:'Saved thought'}});
d('storage-theme','Remembered Theme','Intermediate','localStorage, classList','Restore key "theme" ("dark" or "light") by applying dark to #card only for "dark". Toggle the class and persist the new theme on click.', '<section id="card"><h1>Remember my theme</h1><button id="toggle">Toggle</button></section>', 'const card = document.querySelector("#card");','Read localStorage on startup.|Apply the initial class using a boolean condition.|Persist "dark" or "light" after toggling.','const c=document.querySelector("#card");c.classList.toggle("dark",localStorage.getItem("theme")==="dark");document.querySelector("#toggle").onclick=()=>localStorage.setItem("theme",c.classList.toggle("dark")?"dark":"light");',[check('#card',true,'class:dark'),click('#toggle'),check('#card',false,'class:dark'),{action:'storage',key:'theme',value:'light'},click('#toggle'),{action:'storage',key:'theme',value:'dark'}],['Stored dark theme is applied at startup.','Both theme transitions are saved.'],{storageSeed:{theme:'dark'}});
d('storage-list','Saved Reading List','Advanced','JSON, localStorage, arrays','Restore a JSON array from key "books" into li elements. Invalid JSON should fall back to an empty array. Add trimmed nonempty titles and persist the full array.', '<h1>Reading list</h1><input id="title"><button id="add">Add</button><ul id="books"></ul>', 'let books = [];','Parse saved text inside try/catch.|Render each string using textContent.|After adding, JSON.stringify the entire books array into localStorage.','let books=[];try{const b=JSON.parse(localStorage.getItem("books")||"[]");if(Array.isArray(b))books=b;}catch{}const list=document.querySelector("#books");function render(){list.replaceChildren();books.forEach(t=>{const li=document.createElement("li");li.textContent=t;list.append(li);});}render();document.querySelector("#add").onclick=()=>{const t=document.querySelector("#title").value.trim();if(!t)return;books.push(t);localStorage.setItem("books",JSON.stringify(books));render();};',[check('#books',0,'children.length'),enter('#title',' Orbit '),click('#add'),check('#books li','Orbit'),{action:'storage',key:'books',value:'["Orbit"]'},enter('#title','Leaf'),click('#add'),{action:'storage',key:'books',value:'["Orbit","Leaf"]'}],['Malformed stored JSON does not crash the project.','Titles are rendered and saved as a JSON array.'],{storageSeed:{books:'{broken'}});
d('stopwatch','Stopwatch','Intermediate','timers, setInterval, clearInterval','Start increments seconds once per 1000ms. Repeated Start taps must not create extra intervals. Stop pauses the count; Reset stops and sets it to zero.', '<h1>Stopwatch</h1><output id="seconds">0</output><button id="start">Start</button><button id="stop">Stop</button><button id="reset">Reset</button>', 'let seconds = 0;\nlet timer = null;','Guard Start when timer is not null.|clearInterval(timer) stops future ticks; set timer back to null.|Reset must stop the timer as well as update the display.','let n=0,t=null;const o=document.querySelector("#seconds");const stop=()=>{clearInterval(t);t=null;};document.querySelector("#start").onclick=()=>{if(t!==null)return;t=setInterval(()=>o.textContent=++n,1000);};document.querySelector("#stop").onclick=stop;document.querySelector("#reset").onclick=()=>{stop();o.textContent=n=0;};',[click('#start'),click('#start'),wait(1100),check('#seconds','1'),click('#stop'),wait(1100),check('#seconds','1'),click('#start'),wait(1100),check('#seconds','2'),click('#reset'),wait(1100),check('#seconds','0')],['Multiple Start taps create only one timer.','Stop pauses; Start resumes.','Reset stops the timer and clears the display.']);
d('countdown','Countdown','Intermediate','setInterval, clearInterval, conditionals','Start a countdown from 3, decreasing each second to zero. Ignore Start while running. Stop at zero; a later Start begins at 3 again.', '<h1>Three-second countdown</h1><output id="count">3</output><button id="start">Start</button>', 'let timer = null;','Set count to 3 only when starting an idle countdown.|Guard against a second timer.|Clear the interval and null the timer when count reaches zero.','let t=null;const o=document.querySelector("#count");document.querySelector("#start").onclick=()=>{if(t!==null)return;let n=3;o.textContent=n;t=setInterval(()=>{o.textContent=--n;if(n===0){clearInterval(t);t=null;}},1000);};',[click('#start'),click('#start'),wait(1100),check('#count','2'),wait(2200),check('#count','0'),wait(1100),check('#count','0'),click('#start'),check('#count','3')],['The countdown decreases once per second.','It stops at zero without going negative.','A finished countdown can restart.']);
d('debounce','Debounced Search','Advanced','setTimeout, clearTimeout, closures','On search input, update #result to the latest value only after 300ms without further typing. Cancel the previous pending update on each input.', '<h1>Quiet-time search</h1><input id="search"><output id="result">Waiting</output>', 'let pending;','Keep the timeout id outside the listener.|clearTimeout(pending) cancels the previous scheduled update.|Schedule a new timeout for 300 milliseconds.','let t;document.querySelector("#search").oninput=e=>{clearTimeout(t);const v=e.target.value;t=setTimeout(()=>document.querySelector("#result").textContent=v,300);};',[enter('#search','J'),wait(180),check('#result','Waiting'),enter('#search','JS'),wait(180),check('#result','Waiting'),wait(180),check('#result','JS')],['No result is shown before the quiet interval.','New typing cancels the previous pending result.']);
d('toast','Dismissible Toast','Intermediate','timers, hidden, event listeners','Show #toast on Notify, hide it after 500ms, and reset the hide timer on repeated Notify. Dismiss hides it immediately.', '<h1>Notifications</h1><button id="notify">Notify</button><aside id="toast" hidden>Saved <button id="dismiss">Dismiss</button></aside>', 'const toast = document.querySelector("#toast");\nlet timeout;','Cancel the old hide timeout whenever Notify is clicked.|Show the toast before scheduling the new timeout.|Dismiss should clear the timer and set hidden to true.','const t=document.querySelector("#toast");let id;document.querySelector("#notify").onclick=()=>{clearTimeout(id);t.hidden=false;id=setTimeout(()=>t.hidden=true,500);};document.querySelector("#dismiss").onclick=()=>{clearTimeout(id);t.hidden=true;};',[click('#notify'),check('#toast',false,'hidden'),wait(300),click('#notify'),wait(300),check('#toast',false,'hidden'),wait(300),check('#toast',true,'hidden'),click('#notify'),click('#dismiss'),check('#toast',true,'hidden')],['Notify reveals the toast.','Repeated notification resets its lifetime.','Dismiss hides it immediately.']);
d('undo','Undo Last Task','Advanced','arrays, stack, DOM manipulation','Delete the last li when Delete is clicked, remembering removed text. Undo restores the most recently deleted task to the end. Empty delete and empty undo do nothing.', '<h1>Undo practice</h1><ul id="list"><li>Read</li><li>Build</li></ul><button id="delete">Delete last</button><button id="undo">Undo</button>', 'const removed = [];\nconst list = document.querySelector("#list");','Use an array as a stack for removed text.|Delete reads lastElementChild before removing it.|Undo pops the latest text and appends a fresh li.','const removed=[],list=document.querySelector("#list");document.querySelector("#delete").onclick=()=>{const li=list.lastElementChild;if(li){removed.push(li.textContent);li.remove();}};document.querySelector("#undo").onclick=()=>{if(!removed.length)return;const li=document.createElement("li");li.textContent=removed.pop();list.append(li);};',[click('#undo'),check('#list',2,'children.length'),click('#delete'),click('#delete'),click('#delete'),check('#list',0,'children.length'),click('#undo'),check('#list li','Read'),click('#undo'),check('#list li:last-child','Build')],['Deleting an empty list is safe.','Undo restores tasks in reverse deletion order.','Undo with no history does nothing.']);
d('number-guess','Number Guess Feedback','Beginner','Number, conditionals','The secret is 7. On Check, show "Too low", "Too high", or "Correct" by comparing the input number with the secret.', '<h1>Guess 1–10</h1><input id="guess" type="number" value="1"><button id="check">Check</button><output id="feedback">—</output>', 'const secret = 7;','Convert the string input to a number.|Compare less than and greater than the secret.|The final equality case is Correct.','document.querySelector("#check").onclick=()=>{const n=Number(document.querySelector("#guess").value);document.querySelector("#feedback").textContent=n<7?"Too low":n>7?"Too high":"Correct";};',[enter('#guess','2'),click('#check'),check('#feedback','Too low'),enter('#guess','9'),click('#check'),check('#feedback','Too high'),enter('#guess','7'),click('#check'),check('#feedback','Correct')],['All three comparison outcomes are correct.']);
d('unit-ui','Distance Converter','Beginner','change events, numbers, functions','On input or unit change, show the converted distance with two decimals. "km-mi" multiplies by 0.621371; "mi-km" divides by it.', '<h1>Trail distance</h1><input id="distance" type="number" value="10"><select id="unit"><option value="km-mi">km → miles</option><option value="mi-km">miles → km</option></select><output id="result">—</output>', 'const distance = document.querySelector("#distance");\nconst unit = document.querySelector("#unit");','Write one render function used by both listeners.|Choose multiplication or division based on unit.value.|Format both directions with toFixed(2).','const d=document.querySelector("#distance"),u=document.querySelector("#unit");function render(){const n=Number(d.value);document.querySelector("#result").textContent=(u.value==="km-mi"?n*0.621371:n/0.621371).toFixed(2);}d.oninput=render;u.onchange=render;',[enter('#distance','10'),check('#result','6.21'),enter('#unit','mi-km','change'),check('#result','16.09'),enter('#distance','0'),check('#result','0.00')],['Distance input updates the conversion.','Changing direction recalculates using current input.']);
const apiNote='fetch is a bundled offline simulator. Use relative /api/ URLs only. See Local resources for response data. Each run resets the mock service.';
f('fetch-user','Offline Profile Loader','Intermediate','fetch, async/await','Given user id 1 or 2, fetch /api/users/ID and return the user name.','Build the URL with the input id.|Await fetch, then await response.json().|Return the parsed object’s name property.','return (await(await fetch(`/api/users/${input}`)).json()).name;',[[1,'Ada'],[2,'Lin']],{async:true,note:apiNote});
f('fetch-products','Affordable Supplies','Intermediate','fetch, filter, map','Given a maximum price, fetch /api/products and return names priced at or below that maximum in response order.','Parse the products JSON array.|Filter by price <= input.|Map the remaining records to names.','return (await(await fetch("/api/products")).json()).filter(p=>p.price<=input).map(p=>p.name);',[[5,['Pen','Notebook']],[1,[]],[20,['Pen','Notebook','Lamp']]],{async:true,note:apiNote});
f('fetch-status','Missing Profile','Intermediate','response.ok, fetch, error handling','Given a user id, fetch /api/users/ID. Return the name for an OK response or "User unavailable" otherwise.','HTTP 404 does not make fetch reject.|Inspect response.ok before parsing the success object.|Return the fallback message when ok is false.','const r=await fetch(`/api/users/${input}`);return r.ok?(await r.json()).name:"User unavailable";',[[1,'Ada'],[404,'User unavailable']],{async:true,note:apiNote});
f('fetch-catch','Connection Recovery','Intermediate','try/catch, async/await','Given a path, fetch and return its JSON. If fetch rejects or JSON parsing fails, return {error: "Could not load"}.','Put both awaits inside try.|response.json() can reject too.|Return a consistent error object in catch.','try{return await(await fetch(input)).json();}catch{return {error:"Could not load"};}',[['/api/settings',{theme:'dark',notifications:true}],['/api/network-error',{error:'Could not load'}],['/api/bad-json',{error:'Could not load'}]],{async:true,note:apiNote});
f('parallel','Parallel Dashboard','Advanced','Promise.all, destructuring, fetch','Given user id 1 or 2, load the user and /api/products together and return {name, productCount}.','Start both fetch promises before awaiting.|Destructure the results of Promise.all.|Parse both responses and count the products.','const [u,p]=await Promise.all([fetch(`/api/users/${input}`),fetch("/api/products")]);const [user,products]=await Promise.all([u.json(),p.json()]);return {name:user.name,productCount:products.length};',[[1,{name:'Ada',productCount:3}],[2,{name:'Lin',productCount:3}]],{async:true,note:apiNote});
f('retry','Retry Once','Advanced','loops, async/await, error handling','Given a path, fetch at most twice, retrying a rejection or non-OK status once. Return parsed JSON on success or null after two failures.','Use a two-attempt loop.|Treat non-OK responses as failed attempts.|Return null only after both attempts fail.','for(let i=0;i<2;i++){try{const r=await fetch(input);if(!r.ok)throw Error("HTTP");return await r.json();}catch{}}return null;',[['/api/flaky',{message:'Recovered'}],['/api/network-error',null],['/api/missing',null]],{async:true,note:apiNote+' /api/flaky responds 503 once, then 200.'});
f('pages-api','Collect All Pages','Advanced','fetch, loops, spread syntax','Starting at /api/pages/1, follow response.next until null and return all response.items combined. Input is ignored.','Keep a next-path variable.|Append the current page items using spread.|Replace next with the response next path each iteration.','let next="/api/pages/1",items=[];while(next){const p=await(await fetch(next)).json();items.push(...p.items);next=p.next;}return items;',[[null,['alpha','beta','gamma','delta']]],{async:true,note:apiNote});
f('settled','Resilient Batch','Advanced','Promise.allSettled, fetch, filter','Given an array of paths, load them concurrently and return successful JSON values in input order. Omit rejected and non-OK requests.','Make non-OK responses throw.|Promise.allSettled preserves individual outcomes.|Filter fulfilled results and read their value.','const r=await Promise.allSettled(input.map(async p=>{const r=await fetch(p);if(!r.ok)throw Error("HTTP");return r.json();}));return r.filter(x=>x.status==="fulfilled").map(x=>x.value);',[[['/api/users/1','/api/network-error','/api/users/2'],[{id:1,name:'Ada'},{id:2,name:'Lin'}]],[['/api/missing'],[]],[[],[]]],{async:true,note:apiNote});
f('post','Local RSVP','Advanced','HTTP methods, fetch, JSON.stringify','Given {name}, POST it as JSON to /api/rsvp with Content-Type application/json and return the created JSON record.','fetch accepts an options object.|Set method, headers, and JSON.stringify(input) as body.|Parse the response to get the registered record.','return (await fetch("/api/rsvp",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(input)})).json();',[[{name:'Ada'},{name:'Ada',registered:true}],[{name:'Lin'},{name:'Lin',registered:true}]],{async:true,note:apiNote+' The local endpoint checks method, content type, and a string name.'});
f('module-money','Money Module','Intermediate','modules, named imports','Import formatMoney from "@practice/money" and return its formatted USD string for input.','Use the named import syntax.|Keep the import at module top level.|Call formatMoney(input) from your solve function.','return formatMoney(input);',[[3,'$3.00'],[12.5,'$12.50'],[0,'$0.00']],{imports:'import { formatMoney } from "@practice/money";\n',note:'See Local resources for the bundled module source.'});
f('module-stats','Statistics Module','Advanced','modules, destructuring','Import mean and extent from "@practice/stats". Return {average: mean(input), range: extent(input)} for a numeric array.','Import both named exports.|mean returns null for an empty array.|extent returns [min,max], or null for an empty array.','return {average:mean(input),range:extent(input)};',[[[2,4,9],{average:5,range:[2,9]}],[[],{average:null,range:null}]],{note:'See Local resources for the bundled module source.'});
solutions['module-stats']='import {mean,extent} from "@practice/stats";\n'+solutions['module-stats'];
f('module-dynamic','On-Demand Formatter','Advanced','dynamic import, modules, async/await','Dynamically import "@practice/money" inside solve and return formatMoney(input).','import() returns a promise.|Await the module namespace.|Destructure formatMoney and call it with input.','const {formatMoney}=await import("@practice/money");return formatMoney(input);',[[7,'$7.00'],[0.5,'$0.50']],{async:true,note:'Dynamic imports resolve to bundled module text, including while offline.'});
d('async-ui','Loading State Card','Advanced','async/await, fetch, disabled','On Load, immediately disable the button and show "Loading…". Fetch /api/users/1, display its name, then re-enable the button. Ignore extra Load clicks while busy.','<h1>Profile request</h1><button id="load">Load</button><output id="result">—</output>','const button = document.querySelector("#load");','Set loading state before awaiting.|Parse the user JSON after fetch.|Use finally to re-enable the button.','const b=document.querySelector("#load"),o=document.querySelector("#result");b.onclick=async()=>{if(b.disabled)return;b.disabled=true;o.textContent="Loading…";try{o.textContent=(await(await fetch("/api/users/1")).json()).name;}finally{b.disabled=false;}};',[click('#load'),check('#load',true,'disabled'),check('#result','Loading…'),wait(250),check('#result','Ada'),check('#load',false,'disabled')],['Loading feedback and disabled state appear immediately.','The fetched name appears and the button is re-enabled.']);
d('race-ui','Latest Search Wins','Advanced','closures, async/await, request ordering','On input, fetch /api/search?q= plus the encoded query. Display response.label only for the latest input. An older slow response must not overwrite newer results.','<h1>Search without stale results</h1><input id="search"><output id="result">—</output>','let requestId = 0;','Increment a counter for every input.|Capture its value before awaiting.|Only update when the captured id still matches the newest id.','let latest=0;document.querySelector("#search").oninput=async e=>{const id=++latest;const d=await(await fetch("/api/search?q="+encodeURIComponent(e.target.value))).json();if(id===latest)document.querySelector("#result").textContent=d.label;};',[enter('#search','a'),wait(20),enter('#search','ab'),wait(180),check('#result','Results for ab'),wait(350),check('#result','Results for ab')],['The new response appears first.','The older response cannot overwrite it.']);
d('abort-ui','Cancel a Request','Advanced','AbortController, fetch, error handling','Load starts /api/slow with an AbortController signal and displays "Loading…". Cancel aborts it and displays "Cancelled". An uncancelled request displays "Finished". Ignore Load while busy.','<h1>Cancellable request</h1><button id="load">Load</button><button id="cancel">Cancel</button><output id="status">—</output>','let controller = null;','Create a controller for each request.|Pass its signal to fetch.|Catch AbortError and clear the controller in finally.','let c=null;const o=document.querySelector("#status");document.querySelector("#load").onclick=async()=>{if(c)return;c=new AbortController();o.textContent="Loading…";try{await fetch("/api/slow",{signal:c.signal});o.textContent="Finished";}catch(e){o.textContent=e.name==="AbortError"?"Cancelled":"Error";}finally{c=null;}};document.querySelector("#cancel").onclick=()=>c?.abort();',[click('#load'),check('#status','Loading…'),click('#cancel'),wait(30),check('#status','Cancelled'),wait(600),check('#status','Cancelled'),click('#load'),wait(600),check('#status','Finished')],['Cancellation prevents later success feedback.','A subsequent uncancelled request finishes.']);
const explanations=require('./explanations.cjs');
for(const p of projects){if(!explanations[p.id])throw Error('Missing explanation: '+p.id);p.completionExplanation=explanations[p.id];}
if(projects.length!==100)throw Error(`Expected 100, got ${projects.length}`);
for(const [i,p] of projects.entries()){p.curriculumIndex=i+1;p.conceptFamily=p.concepts[0];if(p.hints.length<3)throw Error(p.id);}
const {formatHtml, formatCss} = require('./format-provided.cjs');
for (const p of projects) { p.displayHtml = formatHtml(p.html); p.displayCss = formatCss(p.css); }
const root=path.join(__dirname,'..');
fs.writeFileSync(path.join(root,'data/projects.js'), '// Generated by scripts/author-curriculum.cjs. Single runtime catalog.\n(function(root){\nconst projects = ' + JSON.stringify(projects,null,2) + ';\nif(typeof module==="object"&&module.exports)module.exports=projects;\nelse root.CodeDailyProjects=projects;\n})(typeof globalThis!=="undefined"?globalThis:this);\n');
fs.writeFileSync(path.join(root,'tests/solutions.json'),JSON.stringify(solutions,null,2)+'\n');
console.log(`Authored ${projects.length} projects.`);
